def transform(grid):
    rows = len(grid)
    if rows == 0:
        return grid

    cols = len(grid[0])
    if cols == 0:
        return grid

    three_pos = []
    two_pos = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                three_pos.append((r, c))
            elif grid[r][c] == 2:
                two_pos.append((r, c))

    if not three_pos or not two_pos:
        return grid

    result = [row[:] for row in grid]

    # Get bounds
    three_min_r = min(p[0] for p in three_pos)
    three_max_r = max(p[0] for p in three_pos)
    three_min_c = min(p[1] for p in three_pos)
    three_max_c = max(p[1] for p in three_pos)
    two_min_r = min(p[0] for p in two_pos)
    two_max_r = max(p[0] for p in two_pos)
    two_min_c = min(p[1] for p in two_pos)
    two_max_c = max(p[1] for p in two_pos)

    # If same column range, vertical fill
    if three_min_c == two_min_c and three_max_c == two_max_c:
        for c in range(three_min_c, three_max_c + 1):
            for r in range(three_min_r, two_min_r):
                if grid[r][c] != 2:
                    result[r][c] = 3
    # If same row range, horizontal fill
    elif three_min_r == two_min_r and three_max_r == two_max_r:
        for r in range(three_min_r, three_max_r + 1):
            for c in range(three_min_c, two_max_c):
                if grid[r][c] != 2:
                    result[r][c] = 3
    # Otherwise L-shape
    else:
        # Find bounding box
        rmin = min(three_min_r, two_min_r)
        rmax = max(three_max_r, two_max_r)
        cmin = min(three_min_c, two_min_c)
        cmax = max(three_max_c, two_max_c)

        conn_r = (three_max_r + two_min_r) // 2

        # Fill from 3s to connector
        for r in range(three_min_r, three_max_r + 1):
            if r < conn_r:
                for c in range(three_min_c, cmax):
                    result[r][c] = 3

        # Fill from connector to 2s
        for r in range(conn_r + 1, two_max_r):
            for c in range(cmin, two_max_c):
                result[r][c] = 3

        # Fill connector row
        for c in range(three_min_c, cmax):
            result[conn_r][c] = 3

    return result
